-- Generated localized release notes.
local _, namespace = ...
namespace.releaseNotesByLocale = {["deDE"]={["sections"]={{["items"]={"Questmeldungen, Gruppenquestlog und Hinweise zum Folgen von Quests greifen jetzt zuverlässiger auf lokal verfügbare Questnamen zurück.","Questmeldungen bleiben in der richtigen Reihenfolge, während Namen geladen werden. Questdetails zeigt jetzt auch verspätet eintreffende Tooltip-Texte korrekt an.","Die Verarbeitung von Questnamen, die von anderen Spielern empfangen werden, wurde verbessert."},["title"]="Korrekturen an Questtexten"}},["version"]="7.1.3",["welcome"]="Zuverlässigere Questtexte in der Sprache deines Clients."},["esES"]={["sections"]={{["items"]={"Los anuncios de misión, el Registro de misiones del grupo y los avisos de seguimiento de misiones ahora utilizan de forma más fiable los nombres de misión disponibles localmente.","Las actualizaciones de misión mantienen su orden mientras se cargan los nombres. Detalles de la misión también se recupera correctamente cuando el texto de la descripción emergente llega con retraso.","Se ha mejorado el tratamiento de los nombres de misión recibidos de otros jugadores."},["title"]="Correcciones en los textos de misión"}},["version"]="7.1.3",["welcome"]="Textos de misión más fiables en el idioma de tu cliente."},["esMX"]={["sections"]={{["items"]={"Los anuncios de misión, el Registro de misiones del grupo y los avisos de seguimiento de misiones ahora utilizan de forma más confiable los nombres de misión disponibles localmente.","Las actualizaciones de misión mantienen su orden mientras se cargan los nombres. Detalles de la misión también se recupera correctamente cuando el texto de la descripción emergente llega con retraso.","Se mejoró el manejo de los nombres de misión recibidos de otros jugadores."},["title"]="Correcciones en los textos de misión"}},["version"]="7.1.3",["welcome"]="Textos de misión más confiables en el idioma de tu cliente."},["frFR"]={["sections"]={{["items"]={"Les annonces de quête, le Journal de quêtes du groupe et les notifications de suivi des quêtes utilisent désormais plus fiablement les noms de quêtes disponibles localement.","Les mises à jour de quête restent dans l’ordre pendant le chargement des noms. La fenêtre Détails de la quête affiche aussi correctement le texte des infobulles lorsqu’il arrive en retard.","Amélioration du traitement des noms de quêtes reçus d’autres joueurs."},["title"]="Corrections des textes de quête"}},["version"]="7.1.3",["welcome"]="Des textes de quête plus fiables dans la langue de votre client."},["itIT"]={["sections"]={{["items"]={"Gli annunci delle missioni, il Registro missioni del gruppo e gli avvisi quando segui le missioni di un altro giocatore ora usano in modo più affidabile i nomi delle missioni disponibili localmente.","Gli aggiornamenti delle missioni restano in ordine durante il caricamento dei nomi. Anche Dettagli della missione si aggiorna correttamente quando il testo del tooltip arriva in ritardo.","Migliorata la gestione dei nomi delle missioni ricevuti dagli altri giocatori."},["title"]="Correzioni ai testi delle missioni"}},["version"]="7.1.3",["welcome"]="Testi delle missioni più affidabili nella lingua del tuo client."},["koKR"]={["sections"]={{["items"]={"퀘스트 알림, 파티 퀘스트 목록, 퀘스트 따라가기 알림에서 클라이언트에 제공되는 퀘스트 이름을 더 안정적으로 사용합니다.","퀘스트 이름을 불러오는 동안에도 업데이트 순서가 유지됩니다. 퀘스트 정보 창도 툴팁 텍스트가 늦게 도착하는 경우 정상적으로 갱신됩니다.","다른 플레이어에게서 받은 퀘스트 이름의 처리 방식을 개선했습니다."},["title"]="퀘스트 텍스트 수정"}},["version"]="7.1.3",["welcome"]="클라이언트 언어에 맞는 퀘스트 텍스트를 더 안정적으로 표시합니다."},["ptBR"]={["sections"]={{["items"]={"Os anúncios de missões, o Registro de missões do grupo e os avisos de acompanhamento de missões agora usam os nomes de missões disponíveis localmente de forma mais confiável.","As atualizações de missões mantêm a ordem enquanto os nomes são carregados. Detalhes da missão também se recupera corretamente quando o texto da dica de interface chega com atraso.","Melhoramos o tratamento dos nomes de missões recebidos de outros jogadores."},["title"]="Correções nos textos de missões"}},["version"]="7.1.3",["welcome"]="Textos de missões mais confiáveis no idioma do seu cliente."},["ruRU"]={["sections"]={{["items"]={"Объявления о заданиях, «Журнал заданий группы» и уведомления о следовании за выбранным заданием теперь надёжнее используют доступные в клиенте названия заданий.","Обновления заданий сохраняют порядок, пока загружаются названия. Окно «Описание задания» также корректно обрабатывает текст подсказки, поступивший с задержкой.","Улучшена обработка названий заданий, полученных от других игроков."},["title"]="Исправления текста заданий"}},["version"]="7.1.3",["welcome"]="Более надёжное отображение текста заданий на языке вашего клиента."},["zhCN"]={["sections"]={{["items"]={"任务通告、队伍任务日志和任务跟随提示现在能更可靠地使用客户端中可用的本地化任务名称。","加载任务名称时，任务更新仍会按顺序显示。任务详情窗口也能在提示文本延迟到达时正确恢复显示。","改进了对其他玩家发送的任务名称的处理。"},["title"]="任务文本修复"}},["version"]="7.1.3",["welcome"]="以客户端语言更可靠地显示任务文本。"},["zhTW"]={["sections"]={{["items"]={"任務通知、隊伍任務日誌和任務跟隨提示現在能更可靠地使用客戶端中可用的本地化任務名稱。","載入任務名稱時，任務更新仍會依序顯示。任務詳情視窗也能在提示文字延遲到達時正確恢復顯示。","改善了對其他玩家傳送的任務名稱的處理。"},["title"]="任務文字修正"}},["version"]="7.1.3",["welcome"]="以客戶端語言更可靠地顯示任務文字。"}}
